CREATE DATABASE IF NOT EXISTS agriiigo CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE agriiigo;

CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(24) NOT NULL,
 email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL,
 role ENUM('FARMER','OWNER','ADMIN') NOT NULL, village VARCHAR(120), latitude DECIMAL(10,7), longitude DECIMAL(10,7),
 is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX idx_users_role(role)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS equipment (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL,
 equipment_type ENUM('Tractor','Harvester','Transportation','Rotavator','Cultivator','Seeder','Plough','Sprayer','Thresher','Land Leveller','Other') NOT NULL,
 brand VARCHAR(100) NOT NULL, model VARCHAR(100) NOT NULL, registration_number VARCHAR(80) UNIQUE,
 registration_status VARCHAR(60), year SMALLINT, hp_or_capacity VARCHAR(80), description TEXT,
 latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, village VARCHAR(120),
 verification_status ENUM('PENDING_VERIFICATION','VERIFIED','REJECTED') NOT NULL DEFAULT 'PENDING_VERIFICATION',
 availability_status ENUM('AVAILABLE','UNAVAILABLE') NOT NULL DEFAULT 'AVAILABLE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(owner_id) REFERENCES users(id), INDEX idx_equipment_search(verification_status,equipment_type,availability_status), INDEX idx_equipment_owner(owner_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS equipment_services (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, equipment_id BIGINT UNSIGNED NOT NULL, service_id BIGINT UNSIGNED NOT NULL,
 pricing_model ENUM('PER_ACRE','PER_HOUR','PER_TRIP','FIXED','QUOTE') NOT NULL, price DECIMAL(12,2) NOT NULL DEFAULT 0,
 minimum_quantity DECIMAL(10,2) NOT NULL DEFAULT 1, description VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_equipment_service(equipment_id,service_id),
 FOREIGN KEY(equipment_id) REFERENCES equipment(id) ON DELETE CASCADE, FOREIGN KEY(service_id) REFERENCES services(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS equipment_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, equipment_id BIGINT UNSIGNED NOT NULL, document_type VARCHAR(80) NOT NULL, storage_key VARCHAR(500) NOT NULL, original_name VARCHAR(255), uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(equipment_id) REFERENCES equipment(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS availability (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, equipment_id BIGINT UNSIGNED NOT NULL, available_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, status ENUM('AVAILABLE','UNAVAILABLE') NOT NULL DEFAULT 'AVAILABLE', UNIQUE KEY uq_availability(equipment_id,available_date,start_time), FOREIGN KEY(equipment_id) REFERENCES equipment(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS unavailable_dates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, equipment_id BIGINT UNSIGNED NOT NULL, date DATE NOT NULL, reason VARCHAR(255), UNIQUE KEY uq_unavailable(equipment_id,date), FOREIGN KEY(equipment_id) REFERENCES equipment(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fields (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, farmer_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, area_acres DECIMAL(10,2) NOT NULL, village VARCHAR(120), notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(farmer_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_fields_farmer(farmer_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookings (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, farmer_id BIGINT UNSIGNED NOT NULL, owner_id BIGINT UNSIGNED NOT NULL, equipment_id BIGINT UNSIGNED NOT NULL,
 service_id BIGINT UNSIGNED NOT NULL, field_id BIGINT UNSIGNED, booking_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME,
 duration DECIMAL(10,2), quantity DECIMAL(10,2) NOT NULL, pricing_model VARCHAR(20) NOT NULL, base_price DECIMAL(12,2) NOT NULL,
 operator_type ENUM('OWNER','DRIVER') NOT NULL DEFAULT 'OWNER', driver_name VARCHAR(120), driver_phone VARCHAR(24),
 estimated_amount DECIMAL(12,2), final_amount DECIMAL(12,2), farmer_notes TEXT, status ENUM('REQUESTED','ACCEPTED','REJECTED','CANCELLED','OWNER_EN_ROUTE','ARRIVED','SERVICE_STARTED','SERVICE_COMPLETED','PAYMENT_PENDING','PAID','COMPLETED') NOT NULL DEFAULT 'REQUESTED',
 rejection_reason VARCHAR(500), cancellation_reason VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(farmer_id) REFERENCES users(id), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(equipment_id) REFERENCES equipment(id), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(field_id) REFERENCES fields(id) ON DELETE SET NULL,
 INDEX idx_booking_farmer(farmer_id,status), INDEX idx_booking_owner(owner_id,status), INDEX idx_booking_slot(equipment_id,booking_date,start_time,status)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS price_adjustments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, owner_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, reason VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS service_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL UNIQUE, owner_id BIGINT UNSIGNED NOT NULL, started_at DATETIME, arrived_at DATETIME, service_started_at DATETIME, service_completed_at DATETIME, ended_at DATETIME, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL UNIQUE, amount DECIMAL(12,2) NOT NULL, method ENUM('CASH','OTHER_MANUAL') NOT NULL, status ENUM('PENDING','PAID') NOT NULL DEFAULT 'PENDING', received_by BIGINT UNSIGNED, notes VARCHAR(500), paid_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, reviewer_id BIGINT UNSIGNED NOT NULL, reviewed_user_id BIGINT UNSIGNED NOT NULL, equipment_id BIGINT UNSIGNED, rating TINYINT UNSIGNED NOT NULL, comment VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_review_booking_reviewer(booking_id,reviewer_id), CHECK(rating BETWEEN 1 AND 5), FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(reviewer_id) REFERENCES users(id), FOREIGN KEY(reviewed_user_id) REFERENCES users(id), FOREIGN KEY(equipment_id) REFERENCES equipment(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, booking_id BIGINT UNSIGNED, notification_type VARCHAR(60) NOT NULL, title VARCHAR(160) NOT NULL, message VARCHAR(500) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE SET NULL, INDEX idx_notifications_user(user_id,is_read,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS disputes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, raised_by BIGINT UNSIGNED NOT NULL, reason VARCHAR(150) NOT NULL, description TEXT NOT NULL, status ENUM('OPEN','UNDER_REVIEW','RESOLVED','REJECTED') NOT NULL DEFAULT 'OPEN', admin_response TEXT, resolution TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, resolved_at DATETIME, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(raised_by) REFERENCES users(id), INDEX idx_disputes_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS location_updates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, owner_id BIGINT UNSIGNED NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE, FOREIGN KEY(owner_id) REFERENCES users(id), INDEX idx_location_latest(booking_id,created_at)) ENGINE=InnoDB;
